(window.TNQ=window.TNQ||[]).push({"terms":{"고정원가":{"d":"조업도가 변해도 관련범위 안에서 총액이 일정하게 발생하는 원가입니다.","r":["변동원가"]},"변동원가":{"d":"조업도가 늘면 총액이 함께 늘고 단위당 금액은 일정한 원가입니다.","r":["고정원가"]},"조업도":{"d":"기업이 설비를 이용하는 정도를 나타내는 생산량 같은 활동 수준입니다.","r":[]},"재공품":{"d":"아직 완성되지 않고 제조 과정에 있는 제품입니다.","r":[]},"직접배분법":{"d":"보조부문비를 보조부문끼리 배분하지 않고 제조부문에만 용역 비율대로 직접 배부하는 방법입니다.","r":["단계배분법","상호배분법"]},"단계배분법":{"d":"정한 순서에 따라 보조부문비를 다른 보조부문과 제조부문에 단계적으로 배부하는 방법입니다.","r":["직접배분법","상호배분법"]},"상호배분법":{"d":"보조부문 상호 간의 용역 수수를 모두 반영해 배분하는 방법으로 배부 순서를 고려하지 않습니다.","r":["직접배분법","단계배분법"]},"작업원가표":{"d":"작업별로 발생한 원가를 집계하는 명세서입니다.","r":[]},"예정배부율":{"d":"제조간접비를 미리 정한 배부기준으로 정상개별원가계산에서 각 작업에 배부하는 비율입니다.","r":[]}},"notes":{"500,000원과 400,000원":"물량 비율대로 결합원가를 나눈 몫은 500,000원과 400,000원입니다.","540,000원과 360,000원":"순실현가능가치 비율로 결합원가를 나눈 두 제품의 몫이 540,000원과 360,000원입니다.","가장 이상적인 배분기준은 인과관계 기준이고, 인과관계를 알기 어려우면 수혜기준이나 부담능력기준을 씀":"인과관계가 가장 좋은 기준이고, 알기 어려우면 수혜기준이나 부담능력기준을 씁니다.","각 제조지시별로 원가계산을 해야 하므로 많은 시간과 비용이 발생":"제조지시마다 원가를 계산해야 해서 시간과 비용이 많이 듭니다.","각 제품을 물리적으로 구분할 수 있게 되는 분리점까지 투입된 원가":"결합원가는 제품을 물리적으로 구분할 수 있는 분리점까지 들어간 원가입니다.","같은 원재료를 같은 공정에 넣어 함께 나오는 서로 다른 두 종류 이상의 제품":"한 공정에서 같은 재료로 동시에 나오는 서로 다른 제품들이 결합제품입니다.","개별작업에 직접 부과할 수 없는 제조간접비를 예정배부율을 이용하여 배부":"직접 부과가 안 되는 제조간접비는 미리 정한 예정배부율로 배부합니다.","개별적으로 원가를 추적해야 하므로 공정별로 원가를 통제하기가 어려움":"제품별로 추적하는 방식이라 공정별 원가통제는 어렵습니다.","관련범위 내에서 조업도 수준과 관계없이 총원가가 일정":"관련범위 안에서는 조업도와 무관하게 총원가가 그대로입니다.","기말재공품의 완성도는 원가배분에서 차이가 없음":"기말재공품의 완성도는 어느 방법이든 원가배분 결과에 차이를 만들지 않습니다.","기초재공품 모두를 당기에 착수하여 완성된 것으로 가정":"선입선출법은 기초재공품을 당기에 시작해 마친 것처럼 가정합니다.","기초재공품이 없다면 계산에 차이가 없음":"기초재공품이 없으면 두 방법의 계산은 같아집니다.","내부 경영 의사결정에 필요한 원가 정보를 제공":"원가 정보의 첫째 목적은 회사 안의 경영 의사결정을 돕는 것입니다.","능률적인 생산조건 하에서는 발생하지 않을 것으로 예상되며 예측할 수 없음":"비정상공손은 능률적으로 생산하면 나오지 않을 것이고 예측도 어려운 공손입니다.","두 의사결정 대체안 간의 총원가의 차액, 즉 증분원가":"차액원가는 두 대안의 총원가 차이로 증분원가라고도 부릅니다.","매출원가 계정의 차변으로 대체":"팔린 제품의 원가는 매출원가 계정의 차변으로 대체됩니다.","모든 보조부문비를 제조부문에 제공하는 용역비율에 따라 제조부문에만 직접 배부":"직접배분법은 보조부문끼리의 거래를 무시하고 제조부문에만 용역 비율대로 나눕니다.","배부기준에 따라 각 작업에 배부":"그 배부율에 배부기준 수치를 곱해 각 작업에 나눠 줍니다.","배분 순서에 따라 결과가 달라짐":"단계배분법은 어느 보조부문부터 배분하느냐에 따라 결과가 달라집니다.","보조부문들 간에 일정한 배부순서에 따라 보조부문비를 단계적으로 다른 보조부문과 제조부문에 배부":"정해 둔 순서대로 보조부문비를 아래 단계의 보조부문과 제조부문에 차례로 배부합니다.","보조부문의 배부순서를 고려할 필요가 없음":"상호배분법은 보조부문끼리 주고받은 용역을 모두 반영하므로 순서를 따질 필요가 없습니다.","분리점에서 개별제품을 팔 때 얻을 수 있는 판매가치의 비율로 배분":"분리점에서 팔 때의 판매가치 비율에 따라 결합원가를 나누는 방법입니다.","상호배분법, 단계배분법, 직접배분법 중 어떤 방법을 사용하더라도 제조부문에 모두 배분":"어느 배분법을 쓰더라도 보조부문 원가는 결국 전부 제조부문으로 넘어갑니다.","손익계산서상 제품 원가에 대한 원가 정보를 제공":"손익계산서에 나가는 제품 원가를 계산하는 것도 목적입니다.","수량·무게·부피 같은 물량의 비율로 배분":"수량이나 무게, 부피 같은 물량 비율로 결합원가를 나눕니다.","예측이 가능하며 단기적으로 통제할 수 없음":"정상공손은 예측은 되지만 단기간에 통제하기 어렵습니다.","원가대상에 직접 추적할 수 없으므로 배부기준을 정하여 배부율을 계산":"제조간접비는 특정 제품에 직접 추적이 안 되어 배부기준을 정하고 배부율을 계산합니다.","원가통제에 필요한 원가 정보를 제공":"원가를 통제하는 데 쓸 정보도 원가 정보가 맡는 역할입니다.","일정 기간동안 실제 발생한 제조간접비를 동일 기간의 실제 배부기준 총수로 나눈 실제배부율에 의하여 개별제품에 배부":"실제배부율은 실제 발생한 제조간접비를 같은 기간의 실제 배부기준 총수로 나눈 값입니다.","작업별 발생원가를 집계하는 명세서":"작업원가표는 작업마다 생긴 원가를 모아 둔 명세서입니다.","작업원가표를 근거로 원가계산":"개별원가계산은 작업원가표를 바탕으로 원가를 계산합니다.","재공품 계정의 대변으로 대체":"완성된 제품의 원가는 재공품 계정 대변으로 빠져나갑니다.","재공품 계정의 차변으로 대체":"이 금액은 재공품 계정의 차변으로 옮겨 적습니다.","재료비, 노무비, 제조경비의 합":"당기총제조원가는 재료비와 노무비와 제조경비를 합한 금액입니다.","재무상태표의 원재료 계정에 계상":"명세서의 기말원재료재고액은 재무상태표의 원재료로 올라갑니다.","재무상태표의 재공품 계정으로 계상":"기말 재공품 원가는 재무상태표의 재공품으로 계상됩니다.","재무상태표의 제품 계정 금액과 같음":"손익계산서의 기말제품재고액은 재무상태표의 제품 금액과 일치합니다.","정상품을 생산하는 과정에서 불가피하게 발생하는 계획된 공손":"정상공손은 정상품을 만들다 보면 어쩔 수 없이 나오는 계획된 공손입니다.","제조간접원가를 기말 전에 배부할 수 없어 제품원가 계산이 지연된다는 단점":"기말이 되어야 배부율이 나오므로 제품원가 계산이 늦어진다는 단점이 있습니다.","제조공장의 임차료는 대표적인 고정원가":"제조공장의 임차료가 고정원가의 대표 예입니다.","제조원가명세서의 당기제품제조원가는 손익계산서의 당기제품제조원가와 일치":"제조원가명세서와 손익계산서에 나온 당기제품제조원가는 금액이 같습니다.","제조원가명세서 작성과 관련이 없음":"판매비와관리비는 제조원가가 아니어서 명세서 작성과 무관합니다.","조선업이나 건설업 등에 적합":"조선업이나 건설업 같은 주문 생산 업종에 어울립니다.","조업도(제품생산량)가 증가함에 따라 단위당 고정원가는 감소":"총액이 같은데 생산량이 늘어 나누는 수가 커지므로 단위당 고정원가는 줄어듭니다.","조업도(제품생산량)가 증가함에 따라 단위당 변동원가는 일정":"생산량이 늘어도 단위당 변동원가는 변하지 않습니다.","조업도가 증가하면 총 변동원가도 증가":"조업도가 오르면 총 변동원가도 같이 오릅니다.","조업도의 변동과 관계없이 일정하게 발생":"조업도가 변해도 같은 금액이 발생하는 원가가 고정원가입니다.","주문받은 개별 제품별로 작성된 작업원가표에 집계하여 원가를 계산":"주문받은 제품별 작업원가표에 원가를 모아서 계산합니다.","주문에 따라 여러 종류의 제품을 소량 생산하는 경우에 맞음":"주문을 받아 여러 제품을 소량씩 만드는 생산에 맞는 방식입니다.","직접원가와 제조간접원가의 구분이 중요":"개별원가계산에서는 직접원가와 제조간접원가를 갈라 두는 일이 핵심입니다.","직접재료비와 직접노무비는 실제발생액을 개별작업에 직접 부과":"직접재료비와 직접노무비는 추정치가 아니라 실제 발생한 금액을 쓴다는 점이 제조간접비와 다릅니다.","직접재료원가, 직접노무원가, 제조간접원가":"제조원가는 직접재료원가, 직접노무원가, 제조간접원가 세 가지로 이뤄집니다.","차선의 대체안을 선택할 경우 얻을 수 있었던 기댓값":"기회원가는 하나를 고르며 포기한 차선책에서 얻을 수 있었던 기댓값입니다.","최종 판매가치에서 추가가공원가와 판매비용을 뺀 금액의 비율로 배분":"최종 판매가치에서 추가가공원가와 판매비를 뺀 금액의 비율로 나누는 방법입니다.","특정 대체안을 선택할 경우 발생되지 않는 원가":"회피가능원가는 그 대안을 고르면 아예 생기지 않게 되는 원가입니다.","특정 제품의 제조를 지시하는 문서":"제조지시서는 어떤 제품을 만들라고 지시하는 문서입니다.","평균법과의 수량 차이는 기초재공품의 완성품 환산량의 차이":"선입선출법과 평균법의 수량 차이는 기초재공품의 완성품환산량 차이에서 나옵니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
